using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;using OperationsRequests.Services;namespace OperationsRequests.Pages.Requests;[Authorize]public class DetailsModel(ApplicationDbContext db,UserManager<ApplicationUser> users,RequestWorkflowService flow,ScopeService scope):PageModel{public TrainingRequest RequestItem{get;set;}=null!;public bool CanAct{get;set;}public List<string> Actions{get;set;}=[];[BindProperty]public string Action{get;set;}="";[BindProperty]public string? Note{get;set;}[BindProperty]public string Version{get;set;}="";public async Task<IActionResult> OnGetAsync(int id){return await Load(id)?Page():NotFound();}public async Task<IActionResult> OnPostAsync(int id){if(!await Load(id))return NotFound();var u=await users.GetUserAsync(User)??throw new UnauthorizedAccessException();var r=await flow.Act(RequestItem,u,await users.GetRolesAsync(u),Action,Note,Convert.FromBase64String(Version));if(!r.Item1){ModelState.AddModelError("",r.Item2);return Page();}return RedirectToPage(new{id});}async Task<bool> Load(int id){var r=await db.TrainingRequests.Include(x=>x.Site).ThenInclude(x=>x.Territory).ThenInclude(x=>x.Country).Include(x=>x.RequestedBy).Include(x=>x.AuditEvents).Include(x=>x.Messages).FirstOrDefaultAsync(x=>x.Id==id);if(r is null)return false;var u=await users.GetUserAsync(User)??throw new UnauthorizedAccessException();var roles=await users.GetRolesAsync(u);if(!scope.CanView(r,u,roles))return false;RequestItem=r;CanAct=r.Status is not RequestStatus.Approved and not RequestStatus.Declined and not RequestStatus.Resolved; var reviewer=roles.Contains(Roles.PlatformAdmin)||(roles.Contains(Roles.CountryOpsManager)&&u.CountryId==r.Site.Territory.CountryId)||(roles.Contains(Roles.TerritoryManager)&&u.TerritoryId==r.Site.TerritoryId); Actions=r.RequestedById==u.Id&&r.Status==RequestStatus.AdditionalInfoRequested?["ProvideInfo"]:reviewer? r.Status switch{RequestStatus.Submitted=>["StartReview"],RequestStatus.UnderReview=>r.Priority==RequestPriority.High&&roles.Contains(Roles.CountryOpsManager)?["RequestInfo","Approve","Decline"]:r.Priority==RequestPriority.High?["RequestInfo","Escalate"]:roles.Contains(Roles.TerritoryManager)||roles.Contains(Roles.PlatformAdmin)?["RequestInfo","Approve","Decline","Escalate"]:[],RequestStatus.Escalated=>roles.Contains(Roles.CountryOpsManager)||roles.Contains(Roles.PlatformAdmin)?["RequestInfo","Approve","Decline"]:[],RequestStatus.Approved=>["Resolve"],_=>[]}:[];CanAct=Actions.Count>0;Version=Convert.ToBase64String(r.RowVersion);return true;}}


